SELECT 
FROM tb_customer_info
WHERE customer_id = #{customerId}
  AND tenant_id = #{tenantId}

SELECT customer_id
FROM tb_customer_info
WHERE tenant_id = #{tenantId}
  AND customer_code = #{customerCode}

    AND customer_id != #{excludeCustomerId}

LIMIT 1

SELECT customer_id
FROM tb_customer_info
WHERE tenant_id = #{tenantId}
  AND btrim(customer_name) = #{customerName}

    AND customer_id != #{excludeCustomerId}

LIMIT 1

SELECT customer_id
FROM tb_customer_info
WHERE tenant_id = #{tenantId}
  AND regexp_replace(business_no, '[^0-9]', '', 'g') = #{businessNo}

    AND customer_id != #{excludeCustomerId}

LIMIT 1
